    metadata: MetaData,
    schema: Union[str, Literal[SchemaConst.RETAIN_SCHEMA]] = RETAIN_SCHEMA,
    referred_schema_fn: Optional[
        Callable[
            [Table, Optional[str], ForeignKeyConstraint, Optional[str]],
            Optional[str],
